// Generated by GitHub Copilot
/**
 * generate-snapshot.mjs — Génère un instantané réel des données CW8.PA
 *
 * Node n'est PAS soumis au CORS : ce script récupère les vraies données
 * Yahoo Finance et les écrit dans data-snapshot.js, embarqué dans le site.
 * Ce fichier sert de source de secours quand le fetch live échoue côté navigateur.
 *
 * Usage: node generate-snapshot.mjs
 */

const TICKER = 'CW8.PA';
const RANGE = '5y';
const INTERVAL = '1d';

const url = `https://query1.finance.yahoo.com/v8/finance/chart/${TICKER}` +
    `?interval=${INTERVAL}&range=${RANGE}`;

const round2 = (v) => (v === null || Number.isNaN(v) ? null : Math.round(v * 100) / 100);

async function main() {
    console.log(`Récupération des données ${TICKER} (${RANGE}, ${INTERVAL})...`);
    const res = await fetch(url, { headers: { Accept: 'application/json' } });
    if (!res.ok) {
        throw new Error(`HTTP ${res.status}`);
    }

    const json = await res.json();
    const result = json?.chart?.result?.[0];
    if (!result) {
        throw new Error('Réponse Yahoo inattendue');
    }

    const timestamps = result.timestamp || [];
    const q = result.indicators.quote[0];

    const rows = timestamps.map((ts, i) => ({
        date: new Date(ts * 1000).toISOString().split('T')[0],
        open: round2(q.open[i]),
        high: round2(q.high[i]),
        low: round2(q.low[i]),
        close: round2(q.close[i]),
        volume: q.volume[i] ?? 0
    })).filter((d) => d.close !== null);

    const generatedAt = new Date().toISOString();
    const header = `// Instantané réel CW8.PA — généré le ${generatedAt}\n` +
        `// Source: Yahoo Finance (${RANGE}, ${INTERVAL}). Régénérer: node generate-snapshot.mjs\n`;
    const body = `window.CW8_SNAPSHOT = ${JSON.stringify(rows)};\n` +
        `window.CW8_SNAPSHOT_META = { generatedAt: "${generatedAt}", ticker: "${TICKER}", points: ${rows.length} };\n`;

    const { writeFileSync } = await import('node:fs');
    writeFileSync('data-snapshot.js', header + body, 'utf8');

    console.log(`OK: ${rows.length} points écrits dans data-snapshot.js`);
    console.log(`Période: ${rows[0].date} → ${rows[rows.length - 1].date}`);
    console.log(`Dernier close: ${rows[rows.length - 1].close} EUR`);
}

main().catch((err) => {
    console.error('Échec:', err.message);
    process.exit(1);
});
